const spellOptions = `-- name: SpellOptions :many
SELECT s.id, s.level, s.school, s.is_ritual,
       COALESCE(array_agg(DISTINCT k.name) FILTER (WHERE k.name IS NOT NULL), '{}')::text[] AS class_names,
       COALESCE(array_agg(DISTINCT sc.class_id) FILTER (WHERE sc.class_id IS NOT NULL), '{}')::uuid[] AS class_ids
FROM dnd.spell s
LEFT JOIN dnd.spell_class sc ON sc.spell_id = s.id
LEFT JOIN dnd.dnd_class k ON k.id = sc.class_id
WHERE s.deleted_at IS NULL
GROUP BY s.id
`

type SpellOptionsRow struct {
	ID         uuid.UUID   `json:"id"`
	Level      int32       `json:"level"`
	School     string      `json:"school"`
	IsRitual   bool        `json:"is_ritual"`
	ClassNames []string    `json:"class_names"`
	ClassIds   []uuid.UUID `json:"class_ids"`
}

// Each live spell's level, school, ritual tag and the classes whose lists have it.
func (q *Queries) SpellOptions(ctx context.Context) ([]SpellOptionsRow, error) {
	rows, err := q.db.Query(ctx, spellOptions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SpellOptionsRow{}
	for rows.Next() {
		var i SpellOptionsRow
		if err := rows.Scan(
			&i.ID,
			&i.Level,
			&i.School,
			&i.IsRitual,
			&i.ClassNames,
			&i.ClassIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

